import React, { useState } from "react";
import { Eye, Save, X } from "lucide-react";
import "../styles/Marketplace.css";

const templates = [
  {
    id: 1,
    name: "Landing dự án cao cấp",
    desc: "Mẫu landing sang trọng, phù hợp cho dự án cao cấp, bất động sản nghỉ dưỡng.",
    thumbnail: "/images/template1.png",
    previewUrl: "https://example.com/preview1",
  },
  {
    id: 2,
    name: "Landing chủ đầu tư",
    desc: "Mẫu giới thiệu chủ đầu tư, tối ưu niềm tin và CTA mạnh.",
    thumbnail: "/images/template2.png",
    previewUrl: "https://example.com/preview2",
  },
  {
    id: 3,
    name: "Landing CTV thu hút khách",
    desc: "Mẫu năng động, hiện đại, phù hợp môi giới trẻ và chiến dịch lead.",
    thumbnail: "/images/template3.png",
    previewUrl: "https://example.com/preview3",
  },
  // ... (bạn có thể thêm nhiều mẫu hơn sau)
];

const Marketplace = () => {
  const [selectedTemplate, setSelectedTemplate] = useState(null);
  const [toast, setToast] = useState(null);

  const handleSaveToLibrary = (template) => {
    const saved = JSON.parse(localStorage.getItem("myTemplates")) || [];
    const exists = saved.find((t) => t.id === template.id);
    if (!exists) {
      saved.push(template);
      localStorage.setItem("myTemplates", JSON.stringify(saved));
      setToast("Đã lưu vào kho cá nhân 🎉");
    } else {
      setToast("Mẫu này đã có trong kho của bạn rồi 💾");
    }

    setTimeout(() => setToast(null), 2500);
  };

  return (
    <div className="marketplace-page">
      {/* HERO */}
      <section className="marketplace-hero fade-in">
        <h1>Kho Giao Diện Landingpage</h1>
        <p>
          Chọn nhanh mẫu giao diện ưng ý — xem thử, chỉnh sửa và lưu ngay vào kho cá nhân của bạn.
        </p>
      </section>

      {/* TEMPLATE LIST */}
      <section className="templates-section fade-in">
        <h2>✨ Mẫu gợi ý nổi bật</h2>

        <div className="templates-grid">
          {templates.map((template) => (
            <div key={template.id} className="template-card">
              <div className="template-thumb">
                <img src={template.thumbnail} alt={template.name} />
              </div>

              <div className="template-info">
                <h3>{template.name}</h3>
                <p>{template.desc}</p>

                <div className="template-actions">
                  <button
                    className="btn-outline"
                    onClick={() => setSelectedTemplate(template)}
                  >
                    <Eye size={16} /> Xem trước
                  </button>
                  <button
                    className="btn-primary"
                    onClick={() => handleSaveToLibrary(template)}
                  >
                    <Save size={16} /> Lưu vào kho
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* MODAL PREVIEW */}
      {selectedTemplate && (
        <div className="modal-overlay">
          <div className="modal-content large">
            <button
              className="modal-close"
              onClick={() => setSelectedTemplate(null)}
            >
              <X size={20} />
            </button>
            <h3 className="modal-title">
              {selectedTemplate.name}
            </h3>
            <div className="iframe-container">
              <iframe
                src={selectedTemplate.previewUrl}
                title="Preview"
                loading="lazy"
              ></iframe>
            </div>
          </div>
        </div>
      )}

      {/* TOAST */}
      {toast && <div className="toast-message">{toast}</div>}
    </div>
  );
};

export default Marketplace;
